// Des: Tests for M12: scroll, load more, consent wall, scripted form steps
// Flo: mock pages > ladder with actions through local Chrome > assert rows, text, caps, refusals
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const acts = @import("nt-brow-acts.zig"); const cfgz = @import("cf-conf-load.zig");
fn cnt(rig: *rigz.Rig, path: []const u8, needle: []const u8) !usize { const rec = (try rig.reco(path)) orelse return 0; return std.mem.count(u8, rec.body, needle); }
test "infinite scroll: all 50 rows collected, equals the declared total" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); rig.lad.acts = .{ .scrl = 30 }; const out = try rig.go("/scroll"); try std.testing.expectEqualStrings("brow", out.vend); try std.testing.expectEqual(@as(usize, 50), try cnt(&rig, "/scroll", "Row number ")); try std.testing.expectEqual(@as(usize, 1), try cnt(&rig, "/scroll", "Total rows: 50")); }
test "scroll cap stops a runaway page" { var conf: cfgz.Conf = .{}; conf.brow_scrl_maxz = 1; var rig: rigz.Rig = undefined; try rig.up(conf); defer rig.down(); try rig.skipNo(); rig.lad.acts = .{ .scrl = 30 }; _ = try rig.go("/scroll"); const rows = try cnt(&rig, "/scroll", "Row number "); try std.testing.expect(rows < 50 and rows >= 10); }
test "load more button clicked until gone: 30 items" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); rig.lad.acts = .{ .clic = "load more" }; _ = try rig.go("/more"); try std.testing.expectEqual(@as(usize, 30), try cnt(&rig, "/more", "Item number ")); }
test "consent wall dismissed through cons_sele_list; without the flag the text stays hidden" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); rig.lad.acts = .{ .cons = true }; _ = try rig.go("/consent"); try std.testing.expectEqual(@as(usize, 1), try cnt(&rig, "/consent", "Secret article body revealed after consent")); var rig2: rigz.Rig = undefined; try rig2.up(.{}); defer rig2.down(); try rig2.skipNo(); rig2.lad.acts = .{ .scrl = 1 }; _ = try rig2.go("/consent"); try std.testing.expectEqual(@as(usize, 0), try cnt(&rig2, "/consent", "Secret article body")); }
test "3-step search form from a steps file: type, click, wait, extract" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); const stp = try acts.stepsRead(rig.aren.allocator(), "[{\"op\":\"type\",\"sele\":\"#q\",\"text\":\"widgets\"},{\"op\":\"click\",\"sele\":\"#go\"},{\"op\":\"waitsel\",\"sele\":\"#results\"},{\"op\":\"extract\",\"sele\":\"#results\"}]", 50); rig.lad.acts = .{ .steps = stp }; _ = try rig.go("/form"); try std.testing.expectEqual(@as(usize, 2), try cnt(&rig, "/form", "Results for widgets: 5 items")); }
test "typing into a password field is refused, never typed" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); const stp = try acts.stepsRead(rig.aren.allocator(), "[{\"op\":\"type\",\"sele\":\"#pw\",\"text\":\"hunter2\"}]", 50); rig.lad.acts = .{ .steps = stp }; try std.testing.expectError(error.BrowFail, rig.go("/form")); try std.testing.expect((try rig.reco("/form")) == null); }
test "step file: too many steps and unknown ops are typed errors" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectError(error.StepLimit, acts.stepsRead(aren.allocator(), "[{\"op\":\"wait\"},{\"op\":\"wait\"},{\"op\":\"wait\"}]", 2)); try std.testing.expectError(error.BadSteps, acts.stepsRead(aren.allocator(), "[{\"op\":\"rm -rf\"}]", 50)); try std.testing.expectError(error.BadSteps, acts.stepsRead(aren.allocator(), "not json", 50)); }
test "actions without a browser are a typed error, never a silent vendor call" { var conf: cfgz.Conf = .{}; conf.brow_path_exec = "/no/such/chrome"; var rig: rigz.Rig = undefined; try rig.up(conf); defer rig.down(); rig.lad.acts = .{ .scrl = 3 }; try std.testing.expectError(error.NoBrowser, rig.go("/scroll")); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); }
test "step time cap: a long wait is cut by brow_time_seco" { var conf: cfgz.Conf = .{}; conf.brow_time_seco = 2; var rig: rigz.Rig = undefined; try rig.up(conf); defer rig.down(); try rig.skipNo(); const stp = try acts.stepsRead(rig.aren.allocator(), "[{\"op\":\"wait\",\"ms\":30000},{\"op\":\"wait\",\"ms\":30000},{\"op\":\"waitsel\",\"sele\":\"#never\"}]", 50); rig.lad.acts = .{ .steps = stp }; try std.testing.expectError(error.BrowFail, rig.go("/form")); }
